(function () {
    var shop1MouseCallbackReady = false;
    var lastCameraWheelTime = 0;
    var cameraWheelCooldown = 0.03;

    function SendCameraWheel(delta) {
        if (!delta || delta === 0) {
            return false;
        }
        var now = Game.GetGameTime();
        if (now - lastCameraWheelTime < cameraWheelCooldown) {
            return true;
        }
        lastCameraWheelTime = now;
        GameEvents.SendCustomGameEventToServer("camera_zoom_override", { delta: delta });
        return true;
    }

    function RegisterShop1MouseCallback(force) {
        if (shop1MouseCallbackReady && !force) {
            return;
        }
        if (!GameUI || !GameUI.SetMouseCallback) {
            return;
        }

        GameUI.SetMouseCallback(function (eventName, arg) {
            if (eventName === "wheeled") {
                var delta = 0;
                if (typeof arg === "number") {
                    delta = arg;
                } else if (arg === "MOUSE_WHEEL_UP") {
                    delta = 1;
                } else if (arg === "MOUSE_WHEEL_DOWN") {
                    delta = -1;
                }
                return SendCameraWheel(delta);
            }
            if (eventName !== "pressed") {
                return false;
            }
            if (arg !== "MOUSE_LEFT" && arg !== 0) {
                return false;
            }

            var now = Game.GetGameTime();
            var cfg = GameUI.CustomUIConfig();
            if (cfg) {
                cfg.last_left_click_time = now;
            }

            var pid = Players.GetLocalPlayer();
            var cursor = GameUI.GetCursorPosition();
            if (cursor && cursor.length >= 2) {
                var clickedTarget = false;
                if (GameUI.FindScreenEntities) {
                    var ents = GameUI.FindScreenEntities(cursor[0], cursor[1]);
                    if (ents && ents.length > 0) {
                        for (var i = 0; i < ents.length; i++) {
                            var e = ents[i];
                            if (e && e.entityIndex && e.entityIndex !== -1) {
                                if (Entities.IsHero && Entities.IsHero(e.entityIndex)) {
                                    clickedTarget = true;
                                    break;
                                }
                                var name = Entities.GetUnitName(e.entityIndex) || "";
                                if (name.indexOf("npc_dota_auto_cast_dummy") === 0) {
                                    clickedTarget = true;
                                    break;
                                }
                            }
                        }
                    }
                }
                if (cfg) {
                    cfg.selection_force_close = !clickedTarget;
                    cfg.selection_force_close_time = now;
                }

                var world = GameUI.GetScreenWorldPosition(cursor[0], cursor[1]);
                if (world) {
                    GameEvents.SendCustomGameEventToServer("shop1_click_select", {
                        x: world[0],
                        y: world[1],
                        z: world[2]
                    });
                }
            }

            var selected = Players.GetSelectedEntities(pid);
            if (!selected || selected.length < 1) {
                return false;
            }

            var ent = selected[0];
            if (!ent || ent < 0) {
                return false;
            }

            var unitName = Entities.GetUnitName(ent) || "";
            if (unitName.indexOf("npc_dota_auto_cast_dummy") !== 0) {
                return false;
            }

            if (!cursor || cursor.length < 2) {
                return false;
            }

            if (GameUI.FindScreenEntities) {
                var ents = GameUI.FindScreenEntities(cursor[0], cursor[1]);
                if (ents && ents.length > 0) {
                    for (var i = 0; i < ents.length; i++) {
                        var e = ents[i];
                        if (e && e.entityIndex && e.entityIndex !== -1) {
                            return false;
                        }
                    }
                }
            }

            var world = GameUI.GetScreenWorldPosition(cursor[0], cursor[1]);
            if (!world) {
                return false;
            }

            Game.PrepareUnitOrders({
                OrderType: dotaunitorder_t.DOTA_UNIT_ORDER_MOVE_TO_POSITION,
                UnitIndex: ent,
                Position: world,
                Queue: false
            });

            return true;
        });

        shop1MouseCallbackReady = true;
    }

    RegisterShop1MouseCallback();
    GameEvents.Subscribe("shop1_mouse_bind", function () {
        RegisterShop1MouseCallback(true);
    });
})();

